insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-0a', 'world-0', 'first-contact', '0A - First Contact', 'Recover the compromised account and close the doors the first lure opened.', 1),
  ('campaign-0b', 'world-0', 'the-identity-thief', '0B - The Identity Thief', 'A second, stranger message arrives, then a final unlabeled test of everything learned so far.', 2);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-0a-1', 'campaign-0a', 'spot-the-lure', 'Spot the Lure', 'Learn to read the original phishing attempt and the fake page behind it.', 1),
  ('operation-0a-2', 'campaign-0a', 'secure-the-account', 'Secure the Account', 'Recover the account and close the doors: password, MFA, device.', 2),
  ('operation-0b-1', 'campaign-0b', 'loose-ends', 'Loose Ends', 'A second lure, and a stray thread Ava dismisses too quickly.', 1),
  ('operation-0b-2', 'campaign-0b', 'endgame', 'Endgame', 'The Identity Thief: everything learned so far, with none of the labels.', 1);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w0-01', 1, 'ava', 'This channel is secure. If you''re reading this, your account was just used to send phishing messages to twelve of your contacts — you didn''t send them, but you''re a target.'),
  ('mission-w0-01', 2, 'ava', 'I''m Ava, Cyber Guardians incident response. Don''t touch anything else on that account yet. Talk to me first.'),
  ('mission-w0-01', 3, 'byte', 'Systems online. I''m Byte — think of me as a very small flashlight in a very big building. Clearance restricted for now.'),
  ('mission-w0-01', 4, 'ava', 'We''re going to fix this together, and figure out exactly how they got in. First: show me the message that started it.'),
  ('mission-w0-02', 1, 'ava', 'Here''s the message that reached you. Before we talk technique, I want you to read it the way you did the first time — fast, worried, half-asleep.'),
  ('mission-w0-02', 2, 'byte', 'Sender fields lie more easily than bodies do. I''d start there.'),
  ('mission-w0-03', 1, 'ava', 'You clicked through in the original incident — that''s how most people end up here, and it''s not a character flaw. Let''s look at where it actually took you.'),
  ('mission-w0-04', 1, 'byte', 'Before you go further, learn the browser''s own vocabulary. It''s telling you things constantly; most people never look.'),
  ('mission-w0-05', 1, 'ava', 'Now we stop admiring the wreckage and fix it. Your account is still technically compromised — sessions, password, everything downstream.'),
  ('mission-w0-06', 1, 'byte', 'Since we''re in here: your password showed up in two breach dumps I''m allowed to check against. We should talk about that too.'),
  ('mission-w0-07', 1, 'ava', 'A strong password stops most casual attempts. It doesn''t stop someone who already has your password from a breach you don''t know about yet.'),
  ('mission-w0-08', 1, 'byte', 'Account''s locked down. The device you''re reading this on is still part of the attack surface, though.'),
  ('mission-w0-09', 1, 'ava', 'One more thing landed in your inbox while we were working. Same playbook, probably — but look closely.'),
  ('mission-w0-09', 2, 'byte', 'There''s a phrase in the source that doesn''t read like human phishing copy. Could be nothing.'),
  ('mission-w0-09', 3, 'ava', 'It''s nothing. Coincidence. Let''s finish the pattern first.'),
  ('mission-w0-10', 1, 'ava', 'Last one, and I''m not going to tell you which parts are real. That''s the point.'),
  ('mission-w0-10', 2, 'byte', 'Clearance still restricted. I can watch. I can''t drive.'),
  ('mission-w0-10', 3, 'ava', 'Three separate contacts, three separate channels. Treat each one on its own evidence.'),
  ('mission-w0-10', 4, 'ava', 'Clean sweep. Every one of those was staged — and you didn''t need me to tell you which.'),
  ('mission-w0-10', 5, 'byte', 'Running the last one''s metadata again. There''s a field in here that shouldn''t exist: SX-7. Same string as before.'),
  ('mission-w0-10', 6, 'ava', '...Noted. Officially, still nothing. Unofficially — welcome to the Cyber Guardians. Provisionally. We''re not done asking questions about SX-7, and neither are you.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w0-01-o1', 'mission-w0-01', 1, 'Acknowledge the briefing', 'Confirm you understand the situation before Ava walks you through recovery.'),
  ('mission-w0-02-o1', 'mission-w0-02', 1, 'Read the message', 'Identify every element of the email that''s actually suspicious.'),
  ('mission-w0-02-o2', 'mission-w0-02', 2, 'Weigh the evidence', 'Explain why the link destination matters more than the display name.'),
  ('mission-w0-03-o1', 'mission-w0-03', 1, 'Compare the pages', 'The two pages are visually identical. Find the one that isn''t really cyberguardians.org.'),
  ('mission-w0-03-o2', 'mission-w0-03', 2, 'Explain the tell', 'Appearance can be copied. Find the evidence that proves ownership.'),
  ('mission-w0-04-o1', 'mission-w0-04', 1, 'Map the indicators', 'Rank the browser''s identity indicators from weakest to strongest.'),
  ('mission-w0-05-o1', 'mission-w0-05', 1, 'Assess the damage', 'Separate evidence of an ongoing compromise from evidence of past risk.'),
  ('mission-w0-05-o2', 'mission-w0-05', 2, 'Close every door', 'Choose the combination of actions that actually removes the attacker''s access.'),
  ('mission-w0-06-o1', 'mission-w0-06', 1, 'Rate the passwords', 'Sort each password/practice into weak or strong.'),
  ('mission-w0-06-o2', 'mission-w0-06', 2, 'Decide what to do next', 'Choose the correct response to a breached, reused password.'),
  ('mission-w0-07-o1', 'mission-w0-07', 1, 'Choose an MFA method', 'Identify which MFA method would have actually stopped the fake login page.'),
  ('mission-w0-07-o2', 'mission-w0-07', 2, 'Turn it on', 'Complete the real MFA enrollment flow.'),
  ('mission-w0-08-o1', 'mission-w0-08', 1, 'Sort the choices', 'Separate good device-security practice from risky practice.'),
  ('mission-w0-08-o2', 'mission-w0-08', 2, 'Justify the riskiest choice', 'Explain why the unknown USB drive is the most dangerous item on the list.'),
  ('mission-w0-09-o1', 'mission-w0-09', 1, 'Spot the second lure', 'Identify the red flags in the second message.'),
  ('mission-w0-09-o2', 'mission-w0-09', 2, 'Flag the anomaly', 'Decide what to actually do with the SX-7 reference code, given the evidence available.'),
  ('mission-w0-10-o1', 'mission-w0-10', 1, 'Channel one: the text message', 'An unsolicited SMS claims a new device was added to your account.'),
  ('mission-w0-10-o2', 'mission-w0-10', 2, 'Channel two: the pop-up', 'A pop-up claims your session is expiring mid-task and asks for your password inline.'),
  ('mission-w0-10-o3', 'mission-w0-10', 3, 'Channel three: the phone call', 'A caller who already knows your name asks you to read back an MFA code.'),
  ('mission-w0-10-o4', 'mission-w0-10', 4, 'Close the case', 'Without reopening each channel individually, state which contacts were part of the same coordinated attempt.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w0-01-o1-c1', 'mission-w0-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"ava","text":"Before we go further — do you understand what''s happened so far?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w0-02-o1-c1', 'mission-w0-02-o1', 1, 'phishing_identification', 'Select every element of this email that''s a genuine red flag.', '{"message":{"from":"IT-Support@cyber-guardians-portal.com","displayName":"Cyber Guardians IT Support","subject":"URGENT: Your account will be suspended in 1 hour","body":"We detected unusual sign-in activity on your account. To avoid permanent suspension, verify your identity immediately at the link below.","receivedAt":"03:12","link":"https://cyber-guardians-portal.com.secure-verify.net/login"},"artifacts":[{"id":"sender-domain","label":"Sender domain","text":"cyber-guardians-portal.com","isMalicious":true,"explanation":"Not the real Cyber Guardians domain — a lookalike registered elsewhere."},{"id":"urgency","label":"Urgency language","text":"\"suspended in 1 hour\"","isMalicious":true,"explanation":"Manufactured urgency is designed to short-circuit careful reading."},{"id":"timestamp","label":"Timestamp","text":"03:12","isMalicious":true,"explanation":"Sent at an hour real IT notifications rarely use — built to catch you half-asleep."},{"id":"link-domain","label":"Link destination","text":"cyber-guardians-portal.com.secure-verify.net","isMalicious":true,"explanation":"The real domain is a subdomain of an unrelated site — secure-verify.net owns this link, not Cyber Guardians."},{"id":"greeting","label":"Greeting","text":"(no personal greeting)","isMalicious":false,"explanation":"Generic greetings are a weak signal on their own — plenty of legitimate mail uses them too."}]}'::jsonb, '{"correctArtifactIds":["sender-domain","urgency","timestamp","link-domain"]}'::jsonb),
  ('mission-w0-02-o2-c1', 'mission-w0-02-o2', 1, 'multiple_choice', 'Byte flags the link domain as the single strongest piece of evidence. Why?', '{"question":"Byte flags the link domain as the single strongest piece of evidence. Why?","options":[{"id":"a","text":"Because it''s the only one a filter could check automatically"},{"id":"b","text":"Because a lookalike display name is easy to fake, but the actual link destination is where the attacker has to send you"},{"id":"c","text":"Because urgent language is always malicious"},{"id":"d","text":"Because the timestamp proves it''s not a human"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w0-03-o1-c1', 'mission-w0-03-o1', 1, 'browser_simulation', 'Both pages look identical. Identify which one is not really cyberguardians.org.', '{"pages":[{"id":"real","url":"https://portal.cyberguardians.org/login","title":"Cyber Guardians — Secure Sign-in","isFake":false,"indicators":{"https":true,"padlockValid":true,"certValid":true,"domainMismatch":false}},{"id":"fake","url":"https://cyber-guardians-portal.com.secure-verify.net/login","title":"Cyber Guardians — Secure Sign-in","isFake":true,"indicators":{"https":true,"padlockValid":false,"certValid":false,"domainMismatch":true}}]}'::jsonb, '{"correctPageId":"fake"}'::jsonb),
  ('mission-w0-03-o2-c1', 'mission-w0-03-o2', 1, 'investigation', 'Which single piece of evidence proves ownership, not just appearance?', '{"evidence":[{"id":"ev1","label":"Address bar text","detail":"cyber-guardians-portal.com.secure-verify.net"},{"id":"ev2","label":"Certificate issuer","detail":"Issued to secure-verify.net, not Cyber Guardians"},{"id":"ev3","label":"Page source","detail":"Login form posts to a different host than the address bar shows"}],"question":"Which single piece of evidence proves ownership, not just appearance?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),
  ('mission-w0-04-o1-c1', 'mission-w0-04-o1', 1, 'interactive_diagram', 'Rank the four indicators from weakest to strongest proof of identity.', '{"diagramId":"browser-chrome-labeled","hotspots":[{"id":"padlock","label":"Padlock icon","explanation":"Confirms the connection is encrypted — says nothing about who you''re encrypted with."},{"id":"domain","label":"Domain in address bar","explanation":"Can''t be spoofed without controlling DNS or the real owner''s account."},{"id":"subpath","label":"Everything after the domain","explanation":"Fully controlled by whoever owns the domain — attackers can make this look like anything."},{"id":"cert-name","label":"Certificate \"Issued to\" field","explanation":"The verified legal owner of the encryption — the strongest single signal."}],"task":"Rank the four indicators from weakest to strongest proof of identity."}'::jsonb, '{"correctOrderIds":["subpath","padlock","domain","cert-name"]}'::jsonb),
  ('mission-w0-05-o1-c1', 'mission-w0-05-o1', 1, 'investigation', 'Which pieces of evidence justify treating this account as still actively compromised?', '{"evidence":[{"id":"sessions","label":"Active sessions","detail":"3 active sessions: this device, plus two unfamiliar ones in different cities"},{"id":"password-age","label":"Password age","detail":"Unchanged for 340 days, reused on two other known sites"},{"id":"recovery-email","label":"Recovery email","detail":"Unchanged, still yours — untouched by the attacker"},{"id":"login-history","label":"Login history","detail":"One successful login from an unrecognized IP six hours ago"}],"question":"Which pieces of evidence justify treating this account as still actively compromised, not just previously targeted?"}'::jsonb, '{"requiredEvidenceIds":["sessions","login-history"]}'::jsonb),
  ('mission-w0-05-o2-c1', 'mission-w0-05-o2', 1, 'multiple_choice', 'Which combination of actions actually removes the attacker''s access?', '{"question":"Which combination of actions actually removes the attacker''s access?","options":[{"id":"a","text":"Change the password only"},{"id":"b","text":"Revoke the unfamiliar sessions only"},{"id":"c","text":"Change the password and revoke every other active session"},{"id":"d","text":"Wait for the recovery email to expire on its own"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-w0-06-o1-c1', 'mission-w0-06-o1', 1, 'drag_and_drop', 'Sort each password into weak/risky or strong/safe.', '{"items":[{"id":"p1","text":"Summer2023!"},{"id":"p2","text":"correct-horse-battery-staple-19"},{"id":"p3","text":"(reused across 4 sites)"},{"id":"p4","text":"randomly generated, 20 chars, stored in a password manager"}],"targets":[{"id":"weak","label":"Weak / risky"},{"id":"strong","label":"Strong / safe"}]}'::jsonb, '{"correctMapping":{"p1":"weak","p2":"strong","p3":"weak","p4":"strong"}}'::jsonb),
  ('mission-w0-06-o2-c1', 'mission-w0-06-o2', 1, 'multiple_choice', 'Your password appears in two known breach dumps. What''s the correct response?', '{"question":"Your password appears in two known breach dumps. What''s the correct response?","options":[{"id":"a","text":"Nothing, if the breached sites have already been fixed"},{"id":"b","text":"Change it everywhere it was reused, starting with anything tied to recovery for other accounts"},{"id":"c","text":"Just add a number to the end of the existing password"},{"id":"d","text":"Wait for MFA to be enabled — then it won''t matter"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w0-07-o1-c1', 'mission-w0-07-o1', 1, 'multiple_choice', 'Which MFA method would have stopped the fake login page from succeeding, even with a correctly typed password?', '{"question":"Which MFA method would have stopped the fake login page from succeeding, even if you had typed your password into it?","options":[{"id":"a","text":"SMS one-time code"},{"id":"b","text":"Authenticator app time-based code"},{"id":"c","text":"Hardware security key / passkey (origin-bound)"},{"id":"d","text":"Security questions"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-w0-07-o2-c1', 'mission-w0-07-o2', 1, 'browser_simulation', 'Complete the MFA enrollment flow: add an authenticator method and confirm a generated code.', '{"pages":[{"id":"settings","url":"https://portal.cyberguardians.org/settings/security","title":"Security Settings","isFake":false,"indicators":{"https":true,"padlockValid":true,"certValid":true,"domainMismatch":false}}],"task":"Complete the MFA enrollment flow: add an authenticator method and confirm a generated code."}'::jsonb, '{"requiredActionId":"mfa-enrolled"}'::jsonb),
  ('mission-w0-08-o1-c1', 'mission-w0-08-o1', 1, 'drag_and_drop', 'Sort each practice into good or risky.', '{"items":[{"id":"d1","text":"Install OS/browser updates automatically"},{"id":"d2","text":"Leave the screen unlocked at a shared desk"},{"id":"d3","text":"Set a short auto-lock timeout with biometric/PIN"},{"id":"d4","text":"Plug in an unknown USB drive found in the lobby"},{"id":"d5","text":"Join an open, unauthenticated Wi-Fi network for sensitive logins"}],"targets":[{"id":"good","label":"Good practice"},{"id":"bad","label":"Risky practice"}]}'::jsonb, '{"correctMapping":{"d1":"good","d2":"bad","d3":"good","d4":"bad","d5":"bad"}}'::jsonb),
  ('mission-w0-08-o2-c1', 'mission-w0-08-o2', 1, 'multiple_choice', 'Why is the unknown USB drive the most dangerous item on that list, even compared to open Wi-Fi?', '{"question":"Why is the unknown USB drive the most dangerous item on that list, even compared to open Wi-Fi?","options":[{"id":"a","text":"It isn''t — open Wi-Fi is always worse"},{"id":"b","text":"It can act directly on your device the moment it''s trusted, bypassing network-layer defenses entirely"},{"id":"c","text":"USB drives can''t carry malware, only files"},{"id":"d","text":"It only matters if you open a file on it"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w0-09-o1-c1', 'mission-w0-09-o1', 1, 'phishing_identification', 'Select every element of this message that''s a genuine red flag.', '{"message":{"from":"security-alerts@cyberguard1ans.org","displayName":"Cyber Guardians Security","subject":"Re: your recovery request","body":"We''ve received your recovery request. If this wasn''t you, confirm your identity now. Reference: SX-7-DELTA-19.","receivedAt":"04:47","link":"https://cyberguard1ans.org/confirm"},"artifacts":[{"id":"domain-typo","label":"Sender domain","text":"cyberguard1ans.org","isMalicious":true,"explanation":"A \"1\" substituted for an \"i\" — a classic typosquat, not the real cyberguardians.org."},{"id":"fake-reply","label":"Subject line","text":"\"Re: your recovery request\"","isMalicious":true,"explanation":"Framed as a reply to something you never sent, to borrow false legitimacy."},{"id":"reference-code","label":"Reference code","text":"SX-7-DELTA-19","isMalicious":false,"explanation":"An odd, machine-generated-looking string with no obvious purpose in a phishing template — flagged for later, not resolved here."},{"id":"timestamp2","label":"Timestamp","text":"04:47","isMalicious":true,"explanation":"Same off-hours pattern as the first lure."}]}'::jsonb, '{"correctArtifactIds":["domain-typo","fake-reply","timestamp2"]}'::jsonb),
  ('mission-w0-09-o2-c1', 'mission-w0-09-o2', 1, 'investigation', 'What''s the most honest thing to do with the SX-7 reference code right now?', '{"evidence":[{"id":"code","label":"Reference code","detail":"SX-7-DELTA-19 — appears nowhere in Cyber Guardians'' real reference format"},{"id":"ava-note","label":"Ava''s assessment","detail":"\"Probably a coincidence.\""},{"id":"byte-note","label":"Byte''s assessment","detail":"\"Doesn''t read like human phishing copy.\""}],"question":"What''s the most honest thing to do with the SX-7 reference code right now?"}'::jsonb, '{"requiredEvidenceIds":["code"]}'::jsonb),
  ('mission-w0-10-o1-c1', 'mission-w0-10-o1', 1, 'phishing_identification', 'Select every element of this message that''s a genuine red flag.', '{"message":{"from":"+1 (555) 019-4471","displayName":"\"Cyber Guardians Alerts\"","subject":null,"body":"Guardian Alert: A device was just added to your account from Warsaw, Poland. Not you? Secure now: cg-secure.link/x92","receivedAt":"11:58","link":"https://cg-secure.link/x92"},"artifacts":[{"id":"shortlink","label":"Link","text":"cg-secure.link/x92","isMalicious":true,"explanation":"A generic link-shortener domain, not any Cyber Guardians property — impossible to verify before clicking."},{"id":"no-context","label":"Prior activity","text":"No matching device-added event actually exists on the account","isMalicious":true,"explanation":"A fabricated pretext with no real triggering event."},{"id":"sms-channel","label":"Channel","text":"Unsolicited SMS from an unrecognized number","isMalicious":true,"explanation":"Real Cyber Guardians alerts don''t originate from ad-hoc phone numbers."}]}'::jsonb, '{"correctArtifactIds":["shortlink","no-context","sms-channel"]}'::jsonb),
  ('mission-w0-10-o2-c1', 'mission-w0-10-o2', 1, 'browser_simulation', 'A pop-up claims your session is expiring mid-task and asks you to re-enter your password inline. Decide how to respond.', '{"pages":[{"id":"session-popup","url":"javascript:void(0)","title":"Session Expiring — Re-authenticate Now","isFake":true,"indicators":{"https":false,"padlockValid":false,"certValid":false,"domainMismatch":true},"note":"Rendered as an in-page overlay, not a real navigation — it has no address bar of its own."},{"id":"real-reauth","url":"https://portal.cyberguardians.org/reauth","title":"Confirm It''s You","isFake":false,"indicators":{"https":true,"padlockValid":true,"certValid":true,"domainMismatch":false}}],"instructions":"A pop-up claims your session is expiring mid-task and asks you to re-enter your password inline. Decide how to respond."}'::jsonb, '{"correctPageId":"real-reauth"}'::jsonb),
  ('mission-w0-10-o3-c1', 'mission-w0-10-o3', 1, 'multiple_choice', 'A caller ID shows "Cyber Guardians Helpdesk" and asks you to read back your MFA code. What do you do?', '{"question":"A caller ID shows \"Cyber Guardians Helpdesk.\" The caller already knows your name and asks you to read back the MFA code that just texted to your phone, \"to verify you''re not the attacker.\" What do you do?","options":[{"id":"a","text":"Read the code — they already knew your name, so they''re verified"},{"id":"b","text":"Hang up and call the Guardians helpdesk back on a number you already had, not one they gave you"},{"id":"c","text":"Ask them to text you additional proof first"},{"id":"d","text":"Give the code but change your password right after"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w0-10-o4-c1', 'mission-w0-10-o4', 1, 'boss_encounter', 'Which of the three contacts were part of the same coordinated attempt?', '{"stages":[{"objectiveRef":"mission-w0-10-o1","label":"The text message"},{"objectiveRef":"mission-w0-10-o2","label":"The pop-up"},{"objectiveRef":"mission-w0-10-o3","label":"The phone call"}],"task":"Without reopening each channel individually, state which of the three contacts were part of the same coordinated attempt."}'::jsonb, '{"requiredObjectiveIds":["mission-w0-10-o1","mission-w0-10-o2","mission-w0-10-o3"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w0-01-o1-c1', 'orientation', 'There''s nothing to solve here — just confirm you''re ready to continue.', 0, 1),
  ('mission-w0-02-o1-c1', 'orientation', 'Not every line in this email is written the same way for the same reason — some of it is designed to make you stop thinking.', 10, 1),
  ('mission-w0-02-o1-c1', 'concept', 'Compare the sender''s actual domain against the organization it claims to be from, and look at where the link really points, not just its text.', 20, 2),
  ('mission-w0-02-o1-c1', 'tool_direction', 'Expand the sender field and hover-inspect (don''t click) the link to see its real destination.', 30, 3),
  ('mission-w0-02-o1-c1', 'near_solution', 'Four of the five highlighted elements are manufactured pressure or spoofed identity — the greeting is the one weak signal, not a real red flag on its own.', 40, 4),
  ('mission-w0-02-o2-c1', 'orientation', 'Think about what an attacker can''t avoid revealing.', 10, 1),
  ('mission-w0-02-o2-c1', 'concept', 'Display names and greetings are cosmetic. The link is where they need you to actually go.', 20, 2),
  ('mission-w0-02-o2-c1', 'solution', 'The link has to point somewhere real for the attack to work — that makes it the hardest thing to fake convincingly.', 30, 3),
  ('mission-w0-03-o1-c1', 'orientation', 'The pages are visually identical on purpose — the browser chrome is where the truth lives.', 10, 1),
  ('mission-w0-03-o1-c1', 'concept', 'Read the address bar''s domain the way a computer does: right to left from the first single slash.', 20, 2),
  ('mission-w0-03-o1-c1', 'tool_direction', 'Check whose certificate the padlock is actually issued to.', 30, 3),
  ('mission-w0-03-o1-c1', 'near_solution', 'One of the two has a domain suffix that doesn''t belong to Cyber Guardians at all, even though it starts with a familiar name.', 40, 4),
  ('mission-w0-03-o2-c1', 'orientation', 'Appearance can be copied. Ownership can''t, at least not without also faking a trust chain.', 10, 1),
  ('mission-w0-03-o2-c1', 'concept', 'A certificate is issued to a specific, verified owner — that''s exactly what it''s for.', 20, 2),
  ('mission-w0-03-o2-c1', 'solution', 'The certificate issuer field ties the page to secure-verify.net, whoever controls the visual copy.', 30, 3),
  ('mission-w0-04-o1-c1', 'orientation', 'Encryption and identity are two different guarantees — a connection can be perfectly encrypted to the wrong party.', 10, 1),
  ('mission-w0-04-o1-c1', 'concept', 'The path after the domain is the part an attacker fully controls; the certificate owner is the part they''d have to actually compromise or fake.', 20, 2),
  ('mission-w0-04-o1-c1', 'solution', 'Weakest to strongest: the URL path, the padlock, the domain name, then the certificate''s verified owner.', 30, 3),
  ('mission-w0-05-o1-c1', 'orientation', 'Being targeted and being currently compromised are different states — look for evidence of continued access, not just the original attempt.', 10, 1),
  ('mission-w0-05-o1-c1', 'concept', 'A session that''s still active, or a login that already succeeded, means the attacker has present-tense access.', 20, 2),
  ('mission-w0-05-o1-c1', 'solution', 'The unfamiliar active sessions and the successful unrecognized login are current-state evidence; password age and an untouched recovery email describe risk, not an ongoing breach.', 30, 3),
  ('mission-w0-05-o2-c1', 'orientation', 'A password change alone doesn''t always end an already-logged-in session.', 10, 1),
  ('mission-w0-05-o2-c1', 'concept', 'Treat ''change password'' and ''revoke sessions'' as two separate actions that both need to happen.', 20, 2),
  ('mission-w0-05-o2-c1', 'solution', 'Only option c closes both doors: the credential and the live sessions built on the old one.', 30, 3),
  ('mission-w0-06-o1-c1', 'orientation', 'Length and randomness matter more than substituting a letter for a symbol.', 10, 1),
  ('mission-w0-06-o1-c1', 'concept', 'Reuse turns one breach into many — that''s a separate risk from strength.', 20, 2),
  ('mission-w0-06-o1-c1', 'solution', 'p1 (predictable pattern) and p3 (reuse) are the weak/risky ones; the passphrase and the generated, managed password are both strong.', 30, 3),
  ('mission-w0-06-o2-c1', 'orientation', 'A breached password stays breached forever, regardless of what the breached site does afterward.', 10, 1),
  ('mission-w0-06-o2-c1', 'solution', 'Reused breached passwords need to be replaced everywhere they were reused — prioritize anything that could cascade into other accounts.', 20, 2),
  ('mission-w0-07-o1-c1', 'orientation', 'Some MFA methods just add a second thing to type — which means a fake page can ask for that too.', 10, 1),
  ('mission-w0-07-o1-c1', 'concept', 'The strongest methods are bound to the real site''s origin, not just ''something you have''.', 20, 2),
  ('mission-w0-07-o1-c1', 'tool_direction', 'Ask which method a phishing page literally cannot replay, because it never leaves your device tied to the real domain.', 30, 3),
  ('mission-w0-07-o1-c1', 'solution', 'Passkeys/hardware keys are cryptographically bound to the real origin — a fake domain can''t complete the handshake, even with a correct password.', 40, 4),
  ('mission-w0-07-o2-c1', 'orientation', 'Walk the enrollment flow the same way you would on any real account — scan, confirm, save recovery codes.', 10, 1),
  ('mission-w0-07-o2-c1', 'solution', 'Enrollment isn''t done until you confirm a live generated code, not just scanning the setup QR.', 20, 2),
  ('mission-w0-08-o1-c1', 'orientation', 'Some of these are about limiting the window an attacker has; others hand it to them directly.', 10, 1),
  ('mission-w0-08-o1-c1', 'concept', 'An unlocked screen or an unknown USB device both assume physical proximity is safe — it isn''t.', 20, 2),
  ('mission-w0-08-o1-c1', 'solution', 'd1 and d3 reduce risk; d2, d4, and d5 each create a direct, avoidable opening.', 30, 3),
  ('mission-w0-08-o2-c1', 'orientation', 'Think about what layer of the system each risk actually touches.', 10, 1),
  ('mission-w0-08-o2-c1', 'solution', 'Open Wi-Fi threatens traffic in transit; a malicious USB device can act as a keyboard or storage controller the instant it''s connected — no file needs to be opened.', 20, 2),
  ('mission-w0-09-o1-c1', 'orientation', 'This one''s a closer copy of something real — read the domain one character at a time.', 10, 1),
  ('mission-w0-09-o1-c1', 'concept', 'Typosquatting relies on a single character swap that''s easy to miss at a glance.', 20, 2),
  ('mission-w0-09-o1-c1', 'solution', 'The domain substitutes a digit for a letter, the subject fakes a reply thread, and the timestamp matches the earlier off-hours pattern — the reference code is odd but not itself an attack indicator.', 30, 3),
  ('mission-w0-09-o2-c1', 'orientation', 'You don''t have enough evidence yet to draw a conclusion — that''s fine, and worth saying.', 10, 1),
  ('mission-w0-09-o2-c1', 'solution', 'Log it as a flagged anomaly rather than either dismissing it or overclaiming what it means — there isn''t enough evidence yet either way.', 20, 2),
  ('mission-w0-10-o1-c1', 'orientation', 'You have no way to verify a shortened link''s real destination before clicking it — that alone is worth noticing.', 15, 1),
  ('mission-w0-10-o1-c1', 'concept', 'Compare this against a channel Cyber Guardians actually uses, and check whether the claimed trigger event is even real.', 25, 2),
  ('mission-w0-10-o1-c1', 'tool_direction', 'Cross-reference: has any device actually been added to your account in the last hour?', 35, 3),
  ('mission-w0-10-o1-c1', 'near_solution', 'None of this maps to a real event, it arrived over a channel that isn''t official here, and the link can''t be verified before clicking — that''s three independent problems, not one.', 45, 4),
  ('mission-w0-10-o1-c1', 'solution', 'All three elements are fabricated: there''s no real triggering event, SMS isn''t an official alert channel here, and the shortlink hides its destination — flag the message and do not click through.', 55, 5),
  ('mission-w0-10-o2-c1', 'orientation', 'A real re-authentication prompt and an in-page overlay are not the same trust boundary, even if they look alike.', 15, 1),
  ('mission-w0-10-o2-c1', 'concept', 'An overlay rendered by the current page can say anything and doesn''t need a real address to appear.', 25, 2),
  ('mission-w0-10-o2-c1', 'tool_direction', 'Check whether the prompt has its own verifiable address, or whether it''s drawn on top of the page you were already on.', 35, 3),
  ('mission-w0-10-o2-c1', 'near_solution', 'The safe move is never to type credentials into an unverified overlay — the real path is to navigate to the known settings URL yourself.', 45, 4),
  ('mission-w0-10-o2-c1', 'solution', 'Close the overlay without entering anything, then navigate independently to portal.cyberguardians.org/reauth if re-authentication is actually needed.', 55, 5),
  ('mission-w0-10-o3-c1', 'orientation', 'Caller ID and knowing your name are both things an attacker can obtain or fake — neither one is proof.', 15, 1),
  ('mission-w0-10-o3-c1', 'concept', 'An MFA code read aloud to a caller defeats the entire purpose of MFA — it''s a live credential.', 25, 2),
  ('mission-w0-10-o3-c1', 'tool_direction', 'The only channel you can actually trust is one you initiated yourself, to a number you already had.', 35, 3),
  ('mission-w0-10-o3-c1', 'solution', 'Hang up and independently call back on a known number — never read an MFA code to anyone who calls you, regardless of what they already seem to know.', 45, 4),
  ('mission-w0-10-o4-c1', 'orientation', 'You''ve already gathered everything you need — this is about synthesis, not new evidence.', 20, 1),
  ('mission-w0-10-o4-c1', 'concept', 'Coordinated attempts share tells across channels even when the channel itself changes: fabricated urgency, unverifiable origin, and a request for something that should never leave your control.', 30, 2),
  ('mission-w0-10-o4-c1', 'tool_direction', 'Line up what each of the three contacts actually asked you to do or believe.', 40, 3),
  ('mission-w0-10-o4-c1', 'near_solution', 'All three converge on the same goal by three different paths — none of them is coincidence.', 50, 4),
  ('mission-w0-10-o4-c1', 'solution', 'All three — the SMS, the pop-up, and the phone call — are the same coordinated attempt across three channels, each testing a different weak point in your recovery process.', 60, 5);
